{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Ranitidine, a polar furan-containing drug with a nitromethylene group, had absolute oral bioavailability of 88 ± 10% after a 20 mg oral dose versus IV in healthy volunteers, supporting high F for the query despite high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Thalidomide, an imide-containing drug structurally related to the hydantoin core of the query, had probably high oral bioavailability of 80–100% in fasting healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Chloramphenicol, a nitroaryl amide antibiotic, had excellent oral bioavailability (>100% relative to the succinate prodrug), supporting high F for a nitro-containing polar drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Nevirapine had absolute oral bioavailability of 91 ± 8% in healthy volunteers, demonstrating that high F is achievable even when physicochemical predictions might be unfavorable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Nitecapone, a nitrocatechol with polar functionality, had oral bioavailability of 38–59% in healthy volunteers, directly supporting F ≥20% for a nitroaromatic polar compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Didanosine, a very polar nucleoside, had absolute oral bioavailability of approximately 43% in patients, supporting high F despite high polarity and low permeability expectations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tivantinib had oral bioavailability of ≥20%, providing a threshold-relevant lower-bound example that supports the high classification.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental records (transfer scores >0.987) from polar, nitro-containing, imide, and nucleoside drugs show oral bioavailability at or above 20%, mostly 40–100%. The low-confidence physicochemical prior is overridden by this consistent experimental evidence. Therefore the query is predicted to have high oral bioavailability (F ≥20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself in the supplied evidence.",
    "The low-confidence physicochemical prior predicts poor permeability, but it is not supported by the transferable experimental data.",
    "Dose-dependent and formulation-dependent effects seen in some analogues (e.g., didanosine) are not directly characterized for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

